function notionBlocksToText(blocks) {
  const lines = [];
  for (const block of blocks) {
    const type = block.type;
    if (type === "divider") {
      lines.push("---");
      continue;
    }
    const richText = block[type]?.rich_text;
    if (!richText) continue;
    const text3 = richText.map((rt) => rt.plain_text || rt.text?.content || "").join("");
    if (!text3.trim()) continue;
    switch (type) {
      case "heading_1":
        lines.push(`# ${text3}`);
        break;
      case "heading_2":
        lines.push(`## ${text3}`);
        break;
      case "heading_3":
        lines.push(`### ${text3}`);
        break;
      case "quote":
        lines.push(`> ${text3}`);
        break;
      case "callout":
        const emoji = block.callout?.icon?.emoji || "\u{1F4CC}";
        lines.push(`${emoji} ${text3}`);
        break;
      case "bulleted_list_item":
        lines.push(`- ${text3}`);
        break;
      case "numbered_list_item":
        lines.push(`\xB7 ${text3}`);
        break;
      case "to_do":
        const checked2 = block.to_do?.checked ? "\u2705" : "\u2B1C";
        lines.push(`${checked2} ${text3}`);
        break;
      case "toggle":
        lines.push(`\u25B6 ${text3}`);
        break;
      case "code":
        lines.push(`\`\`\`
${text3}
\`\`\``);
        break;
      default:
        lines.push(text3);
    }
  }
  return lines.join("\n");
}
